/**
 * Historical logos and photos, downloaded from the files Wikipedia and
 * Wikimedia Commons serve (see `page` for each file's page, author and licence).
 * Generated by scripts/build-media.py; the files live in public/media/.
 */
export interface MediaLogo {
  file: string;
  from: number;
  to?: number;
  page: string;
  license: string;
}

export interface MediaPhoto {
  file: string;
  page: string;
  license: string;
  artist: string;
  caption: string;
}

export const HISTORICAL_LOGOS: Record<string, MediaLogo[]> = {};
export const TEAM_PHOTOS: Record<string, MediaPhoto[]> = {};
export const VENUE_PHOTOS: Record<string, MediaPhoto> = {};
